    17	function clearStorageAndRedirect(errorMessage?: string): Promise<void> {
    18	    // Under certain conditions, there are key-values we'd like to keep in storage even when a user is logged out.
    19	    // We pass these into the clear() method in order to avoid having to reset them on a delayed tick and getting
    20	    // flashes of unwanted default state.
    21	    const keysToPreserve: OnyxKey[] = [];
    22	    keysToPreserve.push(ONYXKEYS.NVP_PREFERRED_LOCALE);
    23	    keysToPreserve.push(ONYXKEYS.ACTIVE_CLIENTS);
    24	    keysToPreserve.push(ONYXKEYS.DEVICE_ID);
    25	
    26	    // After signing out, set ourselves as offline if we were offline before logging out and we are not forcing it.
    27	    // If we are forcing offline, ignore it while signed out, otherwise it would require a refresh because there's no way to toggle the switch to go back online while signed out.
    28	    if (currentIsOffline && !currentShouldForceOffline) {
    29	        keysToPreserve.push(ONYXKEYS.NETWORK);
    30	    }
    31	
    32	    return Onyx.clear(keysToPreserve).then(() => {
    33	        Policy.clearAllPolicies();
    34	        if (!errorMessage) {
    35	            return;
    36	        }
    37	
    38	        // `Onyx.clear` reinitializes the Onyx instance with initial values so use `Onyx.merge` instead of `Onyx.set`
    39	        Onyx.merge(ONYXKEYS.SESSION, {errors: ErrorUtils.getMicroSecondOnyxErrorWithMessage(errorMessage)});
    40	    });
    41	}
